In the systemray we would log it before triggering the suspend:

{noformat}  [[nodiscard]] bool LidUPowerBackend::suspend() const
  {
      logger.log(igel::log::Level::Info, ME)
          << __func__ << ": Enter suspend";

      constexpr auto cmd {"systemctl suspend"};
      try
      {
        Glib::spawn_command_line_async(cmd);
      }
      catch(Glib::Error &e)
      {
        logger.log(igel::log::Level::Error, ME)
          << __func__ << ": Failed to run " << cmd << ": " << e.what();
        return false;
      }
      return true;
  }{noformat}

