26/Feb/24 2:17 PM;712020:ee35277e-d3b2-4b5d-8963-7393d33cf7fc;I did a quick check on the functionality of libcpp-jwt-dev (1.4+ds-3). I was able to decode our token. The checks for the required claims are also working (iat, exp). Unfortunately, the iat check only checks if the field exists and is of the correct type. So this has to be done manually, as it is done for the exp check.

{code:c++}#include <iostream>
#include "jwt/jwt.hpp"

int main() {
  using namespace jwt::params;

  const char* enc_str = "eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzUxMiJ9.eyJmaW5nZXJwcmludCI6IjI3ODdDRUM1NUM5MjE5RTJFNzg3QzFFMDgwOTUwNURCMjRFQ0Q4OTlDOEYxRUJCNzRGMDVGMzUzODQ4MkQ4QzciLCJib2R5Ijp7InVuaXRJZCI6IjcyMkI0MTM3MTQxNCJ9LCJ0eXBlIjoib3MiLCJleHAiOjE3MDkwMjI4NzgsImlhdCI6MTcwODkzNjQ3OH0.qOk66uEJk69YpsjDj-3K-rM3K81sksM4IjVoFaXfG--qz3dwv1MCOdA1Ua0LA3zkww1WURUPCysyG1I41kkc_eR0INu6wpmSe9i-gjy12huzo2Fk6JaFW-ZierqkjN9beKdqhchRcBYYeP2kEaqTMdfXV4Dioatf0aN3jnxT99OnvR1-HsbT7AoLy1zHbZkNAaySRezRqKgJVo6r0GzyU-B77kUKBKq7CotzQmkNAvt5j-C8c70Ij9F4ToccyAgZlyEHYf5E7ZOJ40IOVAtCyLh7tgZk9n8aFtVOmpZ9YtcxqylzSK49BbWwU34xHXE-Nfxnh5p24EZJ6lQzeFb6VsMHsbJyyC0kFiumqdRyQQ7Q_MgfnsLhVmvSbd7xLkhTX8zm6MGmRyE-t83uuoRpmYr0Q1Z0sqsnV5vXsIeLLueesfKOQ4fWAdm0yxnDiQP5Z_aFOCtHrNRsooc5pK-cGYsBUI1Oj3c_t-DaTBiX1ZicFP8mG_8JDOXLje88_fEt9U3psRsn7LI2FJOOp_lqDAVxVemCF-JfKc1_V0pNzfWCiUgx4YJWTSiv1q_UfG_2GfrbFQNBk7VVqJw4jmBmw2wmsmAWgt9t8d30WJpWV7zV36bXeJMAyEgK1YA7RgQWTrag_Th7VOjTZym3-O1lJJOQgOpYW1WPqxiXtE2ZLUE";

  std::error_code ec;
  auto obj = jwt::decode(enc_str, algorithms({"none", "HS256", "HS512"}), ec, verify(false), validate_iat(true));
  std::cout << ec << std::endl;
  std::cout << obj.has_claim("iat") << std::endl;
  std::cout << "iat value: " << obj.payload().get_claim_value<uint64_t>("iat") << std::endl;
  std::cout << obj.has_claim("exp") << std::endl;
  std::cout << "exp value: " << obj.payload().get_claim_value<uint64_t>("exp") << std::endl;

  std::cout << (ec.value() == static_cast<int>(jwt::VerificationErrc::TokenExpired) ) << std::endl;
  return 0;
}{code}

